<div x-data="{ open:false, wave:'', major:'', majorName:'', baseCategories:['Biaya Pendidikan','Buku & Pembelajaran','Seragam & Perlengkapan','Administrasi & Dokumen','Kegiatan & Kesiswaan','Praktik & Kejuruan','Asesmen & Kompetensi','Kesehatan & Perlindungan','Fasilitas & Teknologi','Transportasi & Akomodasi','Kerohanian & Sosial','Lainnya'], categories:['Biaya Pendidikan','Buku & Pembelajaran','Seragam & Perlengkapan','Administrasi & Dokumen','Kegiatan & Kesiswaan','Praktik & Kejuruan','Asesmen & Kompetensi','Kesehatan & Perlindungan','Fasilitas & Teknologi','Transportasi & Akomodasi','Kerohanian & Sosial','Lainnya'], components:[], newCategory:'Biaya Pendidikan', customCategory:'', manageCategories:false, inferCategory(name){ const value=(name||'').toLowerCase(); if(value.includes('seragam')||value.includes('baju')||value.includes('atribut')||value.includes('sepatu')||value.includes('tas')) return 'Seragam & Perlengkapan'; if(value.includes('buku')||value.includes('lks')||value.includes('modul')||value.includes('atlas')||value.includes('alat tulis')) return 'Buku & Pembelajaran'; if(value.includes('formulir')||value.includes('daftar')||value.includes('administrasi')||value.includes('kartu pelajar')||value.includes('dokumen')) return 'Administrasi & Dokumen'; if(value.includes('praktik')||value.includes('kejuruan')||value.includes('bahan praktik')||value.includes('pkl')||value.includes('workshop')) return 'Praktik & Kejuruan'; if(value.includes('study')||value.includes('kegiatan')||value.includes('osis')||value.includes('fortasi')||value.includes('mpls')||value.includes('ekskul')||value.includes('wisata')) return 'Kegiatan & Kesiswaan'; if(value.includes('ujian')||value.includes('tes')||value.includes('asesmen')||value.includes('sertifikasi')) return 'Asesmen & Kompetensi'; if(value.includes('kesehatan')||value.includes('uks')||value.includes('asuransi')||value.includes('medical')) return 'Kesehatan & Perlindungan'; if(value.includes('lab')||value.includes('komputer')||value.includes('internet')||value.includes('teknologi')||value.includes('fasilitas')) return 'Fasilitas & Teknologi'; if(value.includes('transport')||value.includes('angkutan')||value.includes('bus')||value.includes('penginapan')||value.includes('akomodasi')) return 'Transportasi & Akomodasi'; if(value.includes('zakat')||value.includes('infak')||value.includes('sedekah')||value.includes('sosial')||value.includes('rohani')) return 'Kerohanian & Sosial'; if(value.includes('infaq')||value.includes('gedung')||value.includes('spp')||value.includes('pendidikan')||value.includes('pangkal')) return 'Biaya Pendidikan'; return 'Lainnya'; }, add(category){ this.components.push({name:'', category, amount:''}); }, addCustomCategory(){ const category=(this.customCategory||'').trim().replace(/\s+/g,' '); if(!category) return; if(!this.categories.includes(category)) this.categories.push(category); this.newCategory=category; this.add(category); this.customCategory=''; this.manageCategories=false; }, pruneEmpty(){ this.components=this.components.filter(item => String(item.name||'').trim() || Number(item.amount||0)>0); this.categories=[...new Set([...this.baseCategories,...this.components.map(item => item.category).filter(Boolean)])]; }, remove(item){ this.components.splice(this.components.indexOf(item), 1); }, items(category){ return this.components.filter(item => item.category === category); }, total(category){ return this.items(category).reduce((sum,item) => sum + (Number(item.amount)||0),0); }, edit(wave, major, name, items){ this.wave=wave; this.major=major; this.majorName=name; this.components=items.length ? JSON.parse(JSON.stringify(items)).map(item => ({...item, category:(!item.category || item.category === 'Lainnya') ? this.inferCategory(item.name) : item.category})) : [{name:'', category:'Biaya Pendidikan', amount:''}]; this.categories=[...new Set([...this.baseCategories,...this.components.map(item => item.category).filter(Boolean)])]; this.open=true; } }">
